    const uint8_t *buf = (const uint8_t *)buffer;
    lfs_off_t cur_off = off;
    lfs_size_t cur_size = size;
    lfs_block_t cur_block = block;
    uint8_t tmp_buf[256];  // Sufficient for typical cache read sizes

    while (cur_size > 0) {
        lfs_size_t diff = cur_size;

        // Program cache hit
        if (pcache && cur_block == pcache->block && cur_off >= pcache->off && cur_off < pcache->off + pcache->size) {
            diff = lfs_min(diff, pcache->off + pcache->size - cur_off);
            int cmp = memcmp(&pcache->buffer[cur_off - pcache->off], buf, diff);
            if (cmp != 0) return (cmp < 0) ? LFS_CMP_LT : LFS_CMP_GT;
            buf += diff; cur_off += diff; cur_size -= diff; continue;
        }

        // Read cache hit
        if (cur_block == rcache->block && cur_off >= rcache->off && cur_off < rcache->off + rcache->size) {
            diff = lfs_min(diff, rcache->off + rcache->size - cur_off);
            int cmp = memcmp(&rcache->buffer[cur_off - rcache->off], buf, diff);
            if (cmp != 0) return (cmp < 0) ? LFS_CMP_LT : LFS_CMP_GT;
            buf += diff; cur_off += diff; cur_size -= diff; continue;
        }

        // Load block into read cache
        rcache->block = cur_block;
        rcache->off = lfs_aligndown(cur_off, lfs->cfg->read_size);
        lfs_size_t align_up = lfs_alignup(cur_off + hint, lfs->cfg->read_size);
        lfs_size_t align_up2 = lfs_min(align_up, lfs->cfg->block_size);
        rcache->size = lfs_min(lfs_min(align_up2, lfs->cfg->block_size) - rcache->off, lfs->cfg->cache_size);
        int err = lfs->cfg->read(lfs->cfg, rcache->block, rcache->off, rcache->buffer, rcache->size);
        if (err) return err;
        diff = lfs_min(diff, rcache->size);
        int cmp = memcmp(&rcache->buffer[cur_off - rcache->off], buf, diff);
        if (cmp != 0) return (cmp < 0) ? LFS_CMP_LT : LFS_CMP_GT;
